local CoinDieMaker = {}
local PRODUCTS = {
    iron_coin_die = { name = "Železna matrica za kovance", ironCost = 6, woodCost = 1, leatherCost = 1, time = 6, cost = 215, prestige = 5, happiness = 2, description = "Železna matrica za vrezovanje kovancev." },
    bronze_coin_die = { name = "Bronasta matrica za kovance", bronzeCost = 6, ironCost = 1, woodCost = 1, leatherCost = 1, time = 8, cost = 520, prestige = 7, happiness = 3, description = "Bronasta matrica za fine vzorce." },
    silver_coin_die = { name = "Srebrna matrica za kovance", silverCost = 6, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 12, cost = 1250, prestige = 12, happiness = 4, description = "Srebrna matrica za plemiške kovance." },
    gilded_coin_die = { name = "Pozlačena matrica za kovance", goldCost = 1, silverCost = 6, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 16, cost = 2700, prestige = 21, happiness = 5, description = "Pozlačena matrica za dvorne kovance." },
    jewel_set_coin_die = { name = "Draguljasta matrica za kovance", goldCost = 2, silverCost = 6, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 20, cost = 5800, prestige = 37, happiness = 7, description = "Draguljasta matrica za kraljevske kovance." },
    royal_sovereign_coin_die = { name = "Kraljevski suverena matrica za kovance", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 27, cost = 12400, prestige = 71, happiness = 13, description = "Suverena matrica z biseri za krono." },
}
local BUILDINGS = {
    coindie_workshop = { name = "Matricna delavnica", cost = { gold = 395, wood = 175, stone = 165, iron = 12 }, upkeep = 8, qualityBonus = 5 },
    coindie_house = { name = "Matricna hiša", cost = { gold = 1355, wood = 360, stone = 305, silver = 8, iron = 10 }, upkeep = 29, qualityBonus = 18 },
    master_coindie_atelier = { name = "Mojstrski matricni atelje", cost = { gold = 3320, wood = 425, stone = 565, silver = 41, gold = 8 }, upkeep = 78, qualityBonus = 30 },
    sovereign_coindie_palace = { name = "Suverena matricna palača", cost = { gold = 14100, wood = 665, stone = 885, gold = 91, jewel = 20 }, upkeep = 268, qualityBonus = 55, prestigeBonus = 50 },
}
CoinDieMaker.ironStock = 20; CoinDieMaker.bronzeStock = 14; CoinDieMaker.woodStock = 8; CoinDieMaker.leatherStock = 8; CoinDieMaker.silverStock = 8; CoinDieMaker.goldStock = 6; CoinDieMaker.jewelStock = 4; CoinDieMaker.pearlStock = 4
CoinDieMaker.productStock = {}; CoinDieMaker.buildings = {}; CoinDieMaker.maker = nil; CoinDieMaker.activeMaking = {}; CoinDieMaker.totalProducts = 0; CoinDieMaker.dayTimer = 0
function CoinDieMaker.init() CoinDieMaker.ironStock=20; CoinDieMaker.bronzeStock=14; CoinDieMaker.woodStock=8; CoinDieMaker.leatherStock=8; CoinDieMaker.silverStock=8; CoinDieMaker.goldStock=6; CoinDieMaker.jewelStock=4; CoinDieMaker.pearlStock=4; CoinDieMaker.productStock={}; CoinDieMaker.buildings={}; CoinDieMaker.maker=nil; CoinDieMaker.activeMaking={}; CoinDieMaker.totalProducts=0; CoinDieMaker.dayTimer=0; print("[CoinDieMaker] Royal Coin Die Maker System initialized (6 products, 4 buildings)") end
function CoinDieMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CoinDieMaker.maker={name=n or ("Matricar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Matricar najet: %s (spretnost: %d)",CoinDieMaker.maker.name,s),"success") end; return true end
function CoinDieMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CoinDieMaker.build(id) local ok,e=CoinDieMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CoinDieMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CoinDieMaker.getQualityBonus() local b=0; for _,bd in ipairs(CoinDieMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CoinDieMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CoinDieMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CoinDieMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CoinDieMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CoinDieMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CoinDieMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CoinDieMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CoinDieMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CoinDieMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CoinDieMaker.buildings==0 then return false,"Potrebna matricna delavnica" end; if not CoinDieMaker.maker then return false,"Potreben matricar" end; return true end
function CoinDieMaker.make(pt,qty) qty=qty or 1; local ok,e=CoinDieMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CoinDieMaker.ironStock=CoinDieMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CoinDieMaker.bronzeStock=CoinDieMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CoinDieMaker.woodStock=CoinDieMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CoinDieMaker.leatherStock=CoinDieMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CoinDieMaker.silverStock=CoinDieMaker.silverStock-d.silverCost*qty end; if d.goldCost then CoinDieMaker.goldStock=CoinDieMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CoinDieMaker.jewelStock=CoinDieMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CoinDieMaker.pearlStock=CoinDieMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CoinDieMaker.maker then t=math.max(1,t-math.floor(CoinDieMaker.maker.skill/13)) end; table.insert(CoinDieMaker.activeMaking,{id="coindie_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CoinDieMaker.completeMaking(m) local q=1.0+(CoinDieMaker.getQualityBonus()/100); if CoinDieMaker.maker then q=q+(CoinDieMaker.maker.skill/140) end; q=math.min(2.5,q); CoinDieMaker.productStock[m.productType]=(CoinDieMaker.productStock[m.productType] or 0)+m.quantity; CoinDieMaker.totalProducts=CoinDieMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CoinDieMaker.maker then CoinDieMaker.maker.itemsMade=CoinDieMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CoinDieMaker.maker.skill=math.min(100,CoinDieMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Matrica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"coindie.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CoinDieMaker.update(dt) if not _G.state then return end; CoinDieMaker.dayTimer=CoinDieMaker.dayTimer+dt; if CoinDieMaker.dayTimer>=30 then CoinDieMaker.dayTimer=0; for i=#CoinDieMaker.activeMaking,1,-1 do local m=CoinDieMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CoinDieMaker.completeMaking(m); table.remove(CoinDieMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CoinDieMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CoinDieMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CoinDieMaker.getStats() return {ironStock=CoinDieMaker.ironStock,bronzeStock=CoinDieMaker.bronzeStock,woodStock=CoinDieMaker.woodStock,leatherStock=CoinDieMaker.leatherStock,silverStock=CoinDieMaker.silverStock,goldStock=CoinDieMaker.goldStock,jewelStock=CoinDieMaker.jewelStock,pearlStock=CoinDieMaker.pearlStock,productStock=CoinDieMaker.productStock,numBuildings=#CoinDieMaker.buildings,hasMaker=CoinDieMaker.maker~=nil,makerName=CoinDieMaker.maker and CoinDieMaker.maker.name or "—",makerSkill=CoinDieMaker.maker and CoinDieMaker.maker.skill or 0,activeMaking=#CoinDieMaker.activeMaking,totalProducts=CoinDieMaker.totalProducts} end
return CoinDieMaker
